// the pieces a line is made of (a leading '치익—' is the squelch, not said) and the pause after each,
// or null if some part of it has no recording
export function hqClips(text) {
  let s = text.replace(/^치익[—.]*\s*/, '').trim();
  const names = [], gaps = [];
  while (s) {
    let best = '';
    for (const k in HQ_VOX) if (k.length > best.length && s.startsWith(k)) best = k;
    if (!best) return null;
    names.push(HQ_VOX[best]); gaps.push(best.endsWith(',') ? 0.06 : 0.2);
    s = s.slice(best.length).trim();
  }
  return names.length ? { names, gaps } : null;
}
